// === Tab: mySketch ===
let particles = [];
let N = 1020;
let loopSize = 30;

function initParticles(){
	particles = [];
	for(let i=0; i<N; i++){
		particles.push([random()*2-1,random()*2-1]);
	}
}

function setup() {
	initParticles();

	createCanvas(960,960);
}

function rrotate(x,y,theta){
	let ndx = cos(theta)*x + sin(theta)*y;
	let ndy = cos(theta)*y - sin(theta)*x;
	return [ndx, ndy];
}

function render(){
	let renderParticles = [];
	for(let i=0; i<N; i++){
		let [x,y] = particles[i];
		[x,y] = rrotate(x,y,0.5);
		renderParticles.push([x,y]);
	}

	if(bezierMode){
		noFill();
		stroke(20,0,0);
		strokeWeight(10);
		for(let lN=0; lN*loopSize<N; lN++){
			beginShape();
			for(let i=0; i<loopSize+3; i++){
				let ii = lN*loopSize + i%(loopSize);
				curveVertex((renderParticles[ii][0]+1)*width/2, (renderParticles[ii][1]+1)*width/2);
			}
			endShape();
		}
		return;
	}
	noStroke();
	fill(20,0,0);
	for(p of renderParticles){
		ellipse((p[0]+1)*width/2, (p[1]+1)*width/2, 10);
	}
	stroke(0,0,0,40);
	strokeWeight(2);
	noFill();
	for(let i=0; i<N; i++){
		let j=(i+1)%N;
		line((renderParticles[i][0]+1)*width/2, (renderParticles[i][1]+1)*width/2, (renderParticles[j][0]+1)*width/2, (renderParticles[j][1]+1)*width/2);
	}
}

function draw() {
	background(250);
	render();
	for(let i=0; i<10; i++)
	update();
}

function update(){
	let newParticleCoords = [];

	for(let i=0; i<N; i++){
		newParticleCoords.push([...particles[i]]);
	}

	let pushRadius = 0.15;
	for(let i=0; i<N; i++){
		for(let j=0; j<N; j++){
			let dx = particles[i][0]-particles[j][0];
			if(abs(dx)>pushRadius)continue;
			let dy = particles[i][1]-particles[j][1];
			if(abs(dy)>pushRadius)continue;
			let distSq = dx**2 + dy**2;
			if(distSq>pushRadius**2)continue;
			let factor = 0.1/(0.1+distSq/pushRadius**2) - 0.091;
			newParticleCoords[i][0] += dx*factor/2;
			newParticleCoords[i][1] += dy*factor/2;
		}
	}

	let attractionCoef = 0.3;
	for(let i=0; i<N; i++){
		newParticleCoords[i][0] *= 1-attractionCoef*2;
		newParticleCoords[i][1] *= 1-attractionCoef*2;
	}
	for(let i=0; i<N; i++){
		let lN = floor(i/loopSize);
		var j = lN*loopSize + (i+1)%loopSize;
		newParticleCoords[i][0] += attractionCoef * particles[j][0]
		newParticleCoords[i][1] += attractionCoef * particles[j][1]
	}
	for(let i=0; i<N; i++){
		var lN = floor(i/loopSize);
		var j = lN*loopSize + (i-1+N)%loopSize;
		newParticleCoords[i][0] += attractionCoef * particles[j][0]
		newParticleCoords[i][1] += attractionCoef * particles[j][1]
	}
	for(let i=0; i<N-10; i+=10){
		var j = (i+4)%N;
		var ii = i;
		newParticleCoords[ii][0] += attractionCoef * (particles[j][0]-particles[ii][0])*1.3;
		newParticleCoords[ii][1] += attractionCoef * (particles[j][1]-particles[ii][1])*1.3;
		[ii,j] = [j,ii];
		newParticleCoords[ii][0] += attractionCoef * (particles[j][0]-particles[ii][0])*1.3;
		newParticleCoords[ii][1] += attractionCoef * (particles[j][1]-particles[ii][1])*1.3;
	}

	for(let i=0; i<N; i++){
		var distSq = particles[i][0]**2 + particles[i][1]**2;
		newParticleCoords[i][0] *= 0.99 + 0.01/(1+2*distSq);
		newParticleCoords[i][1] *= 0.99 + 0.01/(1+2*distSq);
		//newParticleCoords[i][1] *= 1 - 0.04/(1+35*particles[i][0]**2);
	}

	let brownianCoeff = 0.02;
	if(!brownian)brownianCoeff=0;
	for(let i=0; i<N; i++){
		particles[i][0] = newParticleCoords[i][0] + brownianCoeff*(random()*2-1);
		particles[i][1] = newParticleCoords[i][1] + brownianCoeff*(random()*2-1);
	}
}

let brownian = false;
let bezierMode = false;

function keyPressed(){
	if(key == 'b')brownian = !brownian;
	if(key == 'z')bezierMode = !bezierMode;
}

